<script setup lang="ts">
import { computed, markRaw, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import AwButton from '../../components/AwButton.vue';
import AwNotice from '../../components/AwNotice.vue';
import AwDialog from '../../components/AwDialog.vue';
import { account, accountRequest, accountTransport, type AccountDetails } from '../identity/session';
import { deviceSession as device } from '../suitcase/deviceSession';
import { DirectorClient } from './DirectorClient';
import { DirectorSession } from './DirectorSession';
import { duelNarrationLabel, remoteStopStatus } from './directorState';
import { duelPageUrl, type DuelSide } from './DuelLinks';
import { registerDirectorStop, clearDirectorStop } from './directorStop';

const details = ref<AccountDetails | null>(null), deviceId = ref(''), loading = ref(false), accessError = ref('');
let accountEpoch=0;
const localMatches = (id:string) => device.savedDevice.value.deviceId === id && device.snapshot.value?.source === 'native-device' && device.snapshot.value.phase !== 'disconnected';
const session = reactive(new DirectorSession(markRaw(new DirectorClient(accountTransport)), markRaw({
  matches: localMatches, offline: device.requestOffline, nextVisit: () => device.startVoice(false),
  stop: () => device.stop(), cancelSpeech: () => device.stopVoice(),
})));
const participant = markRaw({canStop:()=>session.canRemoteStop(),busy:()=>session.remoteStop?.pending===true,stop:()=>session.stopThroughBackend(),clear:()=>session.clear()});
const devices = computed(()=>details.value?.devices ?? []);
const privileged = computed(()=>account.value?.roles.some(role=>['Owner','Administrator'].includes(role)) ?? false);
const canOperate = computed(()=>!!account.value && !!devices.value.find(item=>item.deviceId===deviceId.value && item.canOperate));
const canManage = computed(()=>canOperate.value && (privileged.value || details.value?.grants.some(grant=>grant.resourceType==='device' && grant.resourceId===deviceId.value && grant.permission==='manage')));
const online = computed(()=>session.online());
const activeSession = computed(()=>!!session.state?.sessionId && !!session.state.sessionGeneration);
const localConnected = computed(()=>device.snapshot.value?.source==='native-device' && device.snapshot.value.phase!=='disconnected');
const sameLocal = computed(()=>localMatches(deviceId.value));
const offlineAllowed=computed(()=>localConnected.value && (!deviceId.value || sameLocal.value));
const nextReady = computed(()=>sameLocal.value && device.snapshot.value?.voice?.canStart===true && !!device.snapshot.value.readyMask);
const mood=ref('amused'),scope=ref('session'),tone=ref('dry'),tempo=ref('standard'),scene=ref('coronation'),wand=ref(1),offlineWand=ref(1);
const left=ref(''),right=ref(''),duelMode=ref<'autoplay'|'interactive'>('autoplay'),consent=ref(false);
const moods=[['amused','Pobavený'],['bored','Znuděný'],['irritated','Podrážděný'],['confident','Sebejistý'],['suspicious','Podezíravý'],['panicking','Panikařící']];
const tones=[['reserved','Zdrženlivý'],['dry','Suchý'],['adult','Dospělý'],['chaos','Chaos']];
const scenes=[['coronation','Korunovace'],['ministerial-complaint','Ministerská stížnost'],['wand-rebellion','Hůlka protestuje'],['professional-funeral','Teatrální zhroucení'],['luxury-fraud','Luxusní podvod'],['bad-taste-prophecy','Proroctví špatného vkusu'],['shelf-dispute','Spor přihrádek'],['approved-silence','Schválené ticho'],['room-roast','Roast místnosti']];
const overrideReady=computed(()=>online.value && canOperate.value && activeSession.value && session.state?.selectionLocked===false && !!((session.state.readyMask??0)&(1<<(wand.value-1))));
const duelActive=computed(()=>!!session.duel && !['completed','cancelled','expired','interrupted'].includes(session.duel.state.toLowerCase()));
const publicUrl=computed(()=>session.duel ? duelPageUrl(session.state?.publicOrigin??undefined,session.duel.id):null);
function playUrl(side:DuelSide):string|null { const grant=session.duelGrants.get(side);return grant && session.duel?duelPageUrl(session.state?.publicOrigin??undefined,session.duel.id,{side,token:grant.token}):null; }
const confirmation=ref<{label:string;run:()=>Promise<void>}|null>(null);
function confirm(label:string,run:()=>Promise<void>):void { confirmation.value={label,run}; }
async function acceptConfirmation():Promise<void> { const action=confirmation.value;confirmation.value=null;if(action)await action.run(); }
function resetDrafts():void { confirmation.value=null;left.value='';right.value='';consent.value=false; }
async function loadAccess():Promise<void> {
  if(!account.value)return;
  clearDirectorStop();session.clear();resetDrafts();
  const epoch=++accountEpoch;loading.value=true;accessError.value='';
  try { const result=await accountRequest<AccountDetails>('/app/v1/account');if(epoch===accountEpoch){details.value=result;deviceId.value=result.devices?.[0]?.deviceId??'';} }
  catch(error){if(epoch===accountEpoch)accessError.value=(error as Error).message;}
  finally{if(epoch===accountEpoch)loading.value=false;}
}
async function loadState():Promise<void> {if(!deviceId.value || !devices.value.some(item=>item.deviceId===deviceId.value))return;session.bind(deviceId.value);await session.refresh();if(canOperate.value && session.authorized)registerDirectorStop(participant);}
function command(kind:string,value?:string):void {if(canOperate.value)void session.command(kind,value);}
function localStop():void {device.stop();session.feedback='Stop odeslán místní cestou. Fyzické zastavení není změřené.';}
function cancelSpeech():void {device.stopVoice();if(canOperate.value && online.value)void session.command('cancel-speech');}
watch(deviceId,()=>{clearDirectorStop();session.clear();session.selectedDeviceId=deviceId.value;resetDrafts();},{flush:'sync'});
watch(()=>session.state?.eveningId,resetDrafts,{flush:'sync'});
watch(()=>account.value ? `${account.value.id}:${account.value.roles.join(',')}`:'',()=>{++accountEpoch;clearDirectorStop();session.clear();details.value=null;deviceId.value='';loading.value=false;resetDrafts();void loadAccess();},{flush:'sync'});
function visibility():void {if(document.hidden){session.leaveView();resetDrafts();}else if(session.client.deviceId)void session.refresh();}
let timer:ReturnType<typeof setInterval>|undefined;
onMounted(()=>{void loadAccess();document.addEventListener('visibilitychange',visibility);timer=setInterval(()=>{if(!document.hidden && session.authorized && !session.pending)void session.refresh();},5000);});
onBeforeUnmount(()=>{++accountEpoch;if(timer)clearInterval(timer);document.removeEventListener('visibilitychange',visibility);session.leaveView();resetDrafts();});
</script>

<template>
  <div class="director-view">
    <header class="feature-heading"><p class="aw-eyebrow">Provoz · Show Pack</p><h1>Režie kufru</h1><p>Backend řídí návštěvu. Skutečný kufr samostatně potvrzuje provedení; web nepředstírá zvuk ani pohyb.</p><nav class="director-actions"><RouterLink to="/suitcase" class="aw-button aw-button--secondary">Provoz kufru</RouterLink><RouterLink to="/archive/chronicle" class="aw-button aw-button--secondary">Kronika</RouterLink></nav></header>
    <section class="aw-card"><h2>Přístup a vybraný kufr</h2>
      <p v-if="!account">Přihlaste se účtem s oprávněním ke konkrétnímu kufru. Místní offline cesta zůstává samostatná. <RouterLink to="/signin?return=/suitcase/director">Přihlásit se</RouterLink></p>
      <template v-else><p v-if="!loading && !devices.length">Účet nemá dostupný nakonfigurovaný kufr.</p><label for="director-device">Kufr účtu</label><select id="director-device" v-model="deviceId" class="aw-input" :disabled="loading"><option value="" disabled>Vyberte kufr</option><option v-for="item in devices" :key="item.deviceId" :value="item.deviceId">{{ item.deviceId }}</option></select><div class="director-actions"><AwButton :disabled="!deviceId || session.pending" @click="loadState">Načíst režii</AwButton><AwButton variant="secondary" :disabled="loading" @click="loadAccess">Obnovit oprávnění</AwButton></div><p v-if="!canOperate">Tento účet má pouze přehled. Zásahy vyžadují oprávnění k obsluze vybraného kufru.</p></template>
      <AwNotice v-if="accessError" tone="warning">{{accessError}}</AwNotice>
      <p>{{localConnected?`Místní kufr ${device.savedDevice.value.deviceId ?? 'neznámý'}`:'Místní cesta nedostupná'}} · {{session.authorized?'Backend ověřen':'Backend neověřen'}} · {{online?'Čerstvý snapshot':'Před akcí obnovte stav'}}</p>
      <AwNotice v-if="session.feedback" tone="info" role="status">{{session.feedback}} <RouterLink v-if="session.feedback.includes('passkey')" to="/signin?reauth=1&return=/suitcase/director">Ověřit passkey</RouterLink></AwNotice>
    </section>
    <section class="aw-card"><h2>Zastavení</h2><div class="director-actions"><AwButton variant="danger" data-local-stop :disabled="!localConnected" @click="localStop">Stop místně</AwButton><AwButton variant="danger" data-remote-stop :disabled="!canOperate || !session.canRemoteStop()" :busy="session.remoteStop?.pending" @click="session.stopThroughBackend()">Stop přes backend</AwButton><AwButton variant="secondary" :disabled="!localConnected && !(canOperate && online)" @click="cancelSpeech">Ukončit řeč</AwButton></div><p v-if="session.remoteStop" role="status">{{remoteStopStatus(session.state,session.remoteStop,session.refreshedAt)}}</p><p>Místní, backendové a fyzické zastavení jsou samostatné cesty. Neznámý výsledek se neopakuje automaticky.</p></section>
    <template v-if="session.state">
      <section class="aw-card"><h2>Průběh návštěvy</h2><p>Revize {{session.state.revision}} · {{session.state.phase}} · nálada {{session.state.mood.dominant}} · {{session.state.moodScope ?? 'automatic'}} · tón {{session.state.tone}} · tempo {{session.state.tempo}}</p><p v-if="session.state.pendingCue">Zásah čeká ve frontě na vhodnou fázi. TTL je 30 sekund.</p><div class="director-actions"><AwButton :disabled="!canOperate || !online || !nextReady" @click="command('next-visit')">Další návštěva</AwButton><AwButton :disabled="!canOperate || !online || !activeSession" @click="command('quick-finale')">Krátké finále</AwButton><AwButton :disabled="!canOperate || !online || !activeSession" @click="command('guest-leave')">Host odešel</AwButton><AwButton variant="secondary" :disabled="!canOperate || !online" @click="command('cancel-cue')">Zrušit čekající zásah</AwButton></div><p v-if="session.operation" role="status">{{session.operation.status}} ID {{session.operation.id}}</p></section>
      <section class="aw-card"><h2>Dramaturgie</h2><div class="director-fields"><label>Nálada<select v-model="mood" class="aw-input"><option v-for="[value,label] in moods" :key="value" :value="value">{{label}}</option></select></label><label>Rozsah<select v-model="scope" class="aw-input"><option value="session">Tato návštěva</option><option value="evening">Celý večer</option></select></label></div><div class="director-actions"><AwButton :disabled="!canOperate || !online || (scope==='session' && !activeSession)" @click="command(scope==='evening'?'mood-evening':'mood',mood)">Nastavit náladu</AwButton><AwButton variant="secondary" :disabled="!canOperate || !online" @click="command('mood-auto')">Automatická nálada</AwButton></div>
        <div class="director-fields"><label>Tón<select v-model="tone" class="aw-input"><option v-for="[value,label] in tones" :key="value" :value="value">{{label}}</option></select></label><AwButton :disabled="!canOperate || !online || !activeSession" @click="command('tone',tone)">Použít tón</AwButton><label>Tempo<select v-model="tempo" class="aw-input"><option value="standard">Standardní</option><option value="express">Expresní</option></select></label><AwButton :disabled="!canOperate || !online || !activeSession" @click="command('tempo',tempo)">Použít tempo</AwButton><label>Scéna<select v-model="scene" class="aw-input"><option v-for="[value,label] in scenes" :key="value" :value="value">{{label}}</option></select></label><AwButton :disabled="!canOperate || !online || !activeSession" @click="command('scene-twist',scene)">Krátký scénový zásah</AwButton></div>
        <label>Preferovaná přihrádka<select v-model="wand" class="aw-input"><option v-for="slot in 6" :key="slot" :value="slot">{{slot}}</option></select></label><AwButton :disabled="!overrideReady" @click="command('override',String(wand))">Preferovat dostupnou hůlku</AwButton><p>Override je návrh pro aktuální návštěvu, pouze před zamknutím výběru a pro dostupnou přihrádku.</p>
      </section>
      <section class="aw-card"><h2>Ticho a ambient</h2><p>Backend: ticho {{session.state.quiet?'zapnuto':'vypnuto'}}, ambient {{session.state.ambientEnabled?'zapnut':'vypnut'}}. Místní nastavení je odesláno jen totožnému připojenému kufru.</p><div class="director-actions"><AwButton v-for="enabled in [true,false]" :key="String(enabled)" :disabled="!canOperate || !online" @click="command('quiet',enabled?'on':'off')">Ticho {{enabled?'zapnout':'vypnout'}}</AwButton><AwButton v-for="enabled in [true,false]" :key="'ambient'+enabled" :disabled="!canOperate || !online" @click="command('ambient',enabled?'on':'off')">Ambient {{enabled?'zapnout':'vypnout'}}</AwButton><AwButton :disabled="!canOperate || !online" @click="command('ambient-trigger')">Jednorázový ambient</AwButton></div></section>
      <section class="aw-card"><h2>Souboj hostů</h2><AwButton :disabled="!online" @click="session.loadGuests()">Načíst identity a souboje</AwButton><p v-if="!session.identities.length">Souboj vyžaduje dvě dokončené identity stejného večera.</p><div class="director-fields"><label v-for="side in ['left','right'] as const" :key="side">{{side==='left'?'Levý soupeř':'Pravý soupeř'}}<select :value="side==='left'?left:right" class="aw-input" @change="side==='left'?left=($event.target as HTMLSelectElement).value:right=($event.target as HTMLSelectElement).value"><option value="">Vyberte identitu</option><option v-for="identity in session.identities" :key="identity.identityId" :value="identity.identityId">{{identity.displayName}} · {{identity.wandId}}</option></select></label><label>Průběh<select v-model="duelMode" class="aw-input"><option value="autoplay">Automatický</option><option value="interactive">Volby obou soupeřů</option></select></label></div><label><input v-model="consent" type="checkbox"> Oba hosté výslovně souhlasí se soubojem.</label><AwButton :disabled="!canOperate || !online || !consent || !left || !right || left===right" @click="session.createDuel(left,right,duelMode,consent);consent=false">Připravit souboj</AwButton>
        <article v-if="session.duel"><h3>{{session.duel.left.displayName}} × {{session.duel.right.displayName}}</h3><p>{{session.duel.state}} · kolo {{session.duel.round}} · revize {{session.duel.revision}}</p><p>{{duelNarrationLabel(session.duel)}}</p><p v-if="session.duel.result">{{session.duel.result.ending}}</p><div class="director-actions"><AwButton :disabled="!canOperate || !online || !['pending','created','ready'].includes(session.duel.state.toLowerCase())" @click="session.duelAction('start')">Spustit souboj</AwButton><AwButton variant="danger" :disabled="!canOperate || !online || !duelActive" @click="session.duelAction('cancel')">Zrušit souboj</AwButton><a v-if="publicUrl" :href="publicUrl" class="aw-button aw-button--secondary" rel="noreferrer">Veřejný přehled souboje</a></div>
          <p v-if="!publicUrl">Bez bezpečně nakonfigurované veřejné adresy nelze vydat odkaz soupeře.</p><div v-for="side in ['left','right'] as const" :key="side" class="director-link"><strong>{{side==='left'?'Levý':'Pravý'}} soupeř</strong><div class="director-actions"><AwButton :disabled="!canManage || !online || !duelActive || !publicUrl || session.duel.mode!=='interactive'" @click="confirm('Vydat nový herní odkaz? Předchozí odkaz této strany přestane platit.',()=>session.grant(side,false,true))">Vydat odkaz</AwButton><AwButton variant="secondary" :disabled="!canManage || !online || !duelActive || session.duel.mode!=='interactive'" @click="confirm('Odvolat herní odkaz této strany?',()=>session.grant(side,true,true))">Odvolat odkaz</AwButton><a v-if="playUrl(side)" :href="playUrl(side)!" rel="noreferrer" class="aw-button aw-button--secondary">Odkaz pro soupeře</a></div><p v-if="session.duelGrants.get(side)">Platnost nejdéle do {{session.duelGrants.get(side)?.expiresAt}}. Kopie žije pouze v paměti tohoto pohledu.</p></div>
        </article>
      </section>
      <section class="aw-card"><h2>Proroctví a závěr večera</h2><AwButton :disabled="!online" @click="session.loadProphecies()">Načíst proroctví</AwButton><article v-for="prophecy in session.prophecies" :key="prophecy.outcomeId"><h3>{{prophecy.omen}}</h3><p>{{['unlocked','revealed'].includes(prophecy.state)?'Odhaleno návštěvníkovi. Soukromé znění zůstává v jeho památce.':`Uzamčeno do ${prophecy.unlockAt}`}}</p><AwButton v-if="!['unlocked','revealed'].includes(prophecy.state)" :disabled="!canOperate || !online" @click="confirm('Odhalit toto proroctví návštěvníkovi?',()=>session.reveal(prophecy.outcomeId,true))">Odhalit proroctví</AwButton></article><AwButton variant="danger" :disabled="!canOperate || !online" @click="confirm('Uzavřít aktivní večer? Probíhající návštěva musí být nejprve dokončena. Archiv se nemaže.',()=>session.endEvening(true))">Ukončit večer</AwButton><RouterLink to="/archive/chronicle">Otevřít kroniku</RouterLink></section>
    </template>
    <section class="aw-card"><h2>Místní offline repertoár</h2><p>Místní cíl: {{device.savedDevice.value.deviceId ?? 'žádný'}}. <strong v-if="localConnected && deviceId && !sameLocal">Vybraný účetní kufr je jiný. Místní Show povely jsou zablokované.</strong></p><p>Vyžaduje skutečný připojený kufr. Arm potřebuje předem získaný ruční lease v Provozu. Režie nezískává lease sama. Webová ukázka nemá fyzické výstupy.</p><div class="director-actions"><AwButton :disabled="!offlineAllowed || session.pending" @click="session.offline('offline_preflight')">Ověřit místní banku</AwButton><AwButton :disabled="!offlineAllowed || session.pending" @click="session.offline('offline_arm')">Arm místně</AwButton></div><label>Offline přihrádka<select v-model="offlineWand" class="aw-input"><option v-for="slot in 6" :key="slot" :value="slot">{{slot}}</option></select></label><div class="director-actions"><AwButton :disabled="!offlineAllowed || session.pending" @click="session.offline('offline_start',offlineWand,{shortVariant:false})">Spustit offline</AwButton><AwButton :disabled="!offlineAllowed || session.pending" @click="session.offline('offline_start',offlineWand,{shortVariant:true})">Krátká offline varianta</AwButton><AwButton v-for="enabled in [true,false]" :key="'quiet'+enabled" :disabled="!offlineAllowed || session.pending" @click="session.offline('quiet',undefined,{enabled})">Místní ticho {{enabled?'zapnout':'vypnout'}}</AwButton><AwButton v-for="enabled in [true,false]" :key="'localambient'+enabled" :disabled="!offlineAllowed || session.pending" @click="session.offline('offline_ambient',undefined,{enabled})">Místní ambient {{enabled?'zapnout':'vypnout'}}</AwButton><AwButton :disabled="!canOperate || !online || !sameLocal" @click="confirm('Importovat místní výsledky jako operator_relay? Server je ověří; přijetí není důkaz přehrání.',()=>session.syncOffline(true))">Importovat výsledky</AwButton></div><pre v-if="session.offlineState" class="director-technical">{{session.offlineState}}</pre></section>
    <AwDialog :open="!!confirmation" title="Potvrzení změny" @close="confirmation=null"><p>{{confirmation?.label}}</p><AwButton @click="acceptConfirmation">Potvrdit změnu</AwButton><p>Citlivá změna vyžaduje aktuální passkey. Neznámý výsledek se automaticky neopakuje.</p></AwDialog>
  </div>
</template>
<style scoped>
.director-view{display:grid;gap:var(--aw-space-6);max-width:72rem;margin-inline:auto}.director-actions{display:flex;flex-wrap:wrap;gap:var(--aw-space-3);margin-block:var(--aw-space-3)}.director-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,14rem),1fr));gap:var(--aw-space-3);align-items:end;margin-block:var(--aw-space-4)}.director-fields label{display:grid;gap:var(--aw-space-2)}.director-link{border-top:1px solid var(--aw-border-subtle);padding-block:var(--aw-space-4)}.director-technical{white-space:pre-wrap;overflow-wrap:anywhere;max-height:18rem;overflow:auto}.director-view select{max-width:100%}.director-view article{margin-block:var(--aw-space-4)}
</style>
